{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "In humans, SAHA absolute oral bioavailability was 43% after 200 and 400 mg oral doses in the fasting state, exceeding the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Solifenacin absolute oral bioavailability was 88% (95% CI 75.8–102.1) versus IV in healthy adult volunteers, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Probenecid oral bioavailability was 100% in humans, with oral plasma concentrations identical to IV administration, supporting high bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All condition-matched numeric records across the transferred molecules show absolute oral bioavailability at or above 20%, mostly in the 30–100% range, so high bioavailability is supported.",
  "evidence_gaps": [
    "One record under Molecule 3 (C11) appears to describe morphine rather than pethidine and was discounted as a provenance conflict.",
    "Molecule 5 includes qualitative 'low' reports and a wide range of 7–82%, but the strongest absolute normal-subject record is 32 ± 7%, still above the threshold.",
    "No direct numeric record with F < 20% was supplied."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

